<script lang="ts">
 let {snapshot,hydratedReady,sourceType=$bindable(),sourceName=$bindable(),materialUsed=$bindable(),evidenceRefs=$bindable(),statement=$bindable(),sourceId=$bindable(),revokeReason=$bindable(),sync}:{snapshot:any;hydratedReady:boolean;sourceType:string;sourceName:string;materialUsed:string;evidenceRefs:string[];statement:string;sourceId:string;revokeReason:string;sync:(action:string,extra?:Record<string,unknown>)=>Promise<boolean>}=$props();
 let disabled=$derived(!hydratedReady||!snapshot.capabilities?.attestSource);
 function toggle(file:string,event:Event){const checked=(event.currentTarget as HTMLInputElement).checked;evidenceRefs=checked?[...new Set([...evidenceRefs,file])]:evidenceRefs.filter(x=>x!==file);}
</script>
<section class="space-y-3 rounded border p-4"><h2 class="text-xl">Named source attribution</h2><p>Record who supplied the conviction and which approved material they used. Select source files as evidence; the acting user is identified by the service.</p>{#if snapshot.capabilities?.attestSource}<label>Source type<select class="ml-2" bind:value={sourceType} disabled={disabled}><option value="single founder / owner">Single founder or owner</option><option value="co-founders or leadership team">Co-founders or leadership team</option><option value="practitioner for a client">Practitioner for a client</option></select></label><label class="block">Source name<input class="ml-2" bind:value={sourceName} disabled={disabled}/></label><label class="block">Material used<input class="ml-2" bind:value={materialUsed} disabled={disabled}/></label><fieldset><legend>Evidence files</legend>{#each snapshot.source?.files??[] as file}<label class="mr-3"><input type="checkbox" checked={evidenceRefs.includes(file)} onchange={(e)=>toggle(file,e)} disabled={disabled}/>{file}</label>{/each}</fieldset><label class="block">Attribution statement<textarea class="block w-full" bind:value={statement} disabled={disabled}></textarea><span>{Math.max(0,10-statement.trim().length)} more characters required</span></label><button disabled={disabled||!sourceName.trim()||!materialUsed.trim()||statement.trim().length<10||!evidenceRefs.length} onclick={()=>sync('attest-source',{type:sourceType,name:sourceName,materialUsed,evidenceRefs,statement}).then(saved=>{if(saved){sourceName='';materialUsed='';evidenceRefs=[];statement='';}})}>Record source attribution</button>{:else}<p>Source attribution is managed by the engagement owner.</p>{/if}
 <h3 class="font-medium">Recorded attributions</h3>{#each snapshot.attributions??[] as attribution}<article class="rounded border p-3"><p><strong>{attribution.name}</strong> · {attribution.type}{#if attribution.revokedAt} · Revoked{/if}</p><p>{attribution.statement}</p><p>Material: {attribution.materialUsed}; evidence: {attribution.evidenceRefs.join(', ')}</p>{#if !attribution.revokedAt}{#if snapshot.capabilities?.attestSource}<label>Revocation reason<input class="ml-2" bind:value={revokeReason} disabled={!hydratedReady}/></label><button disabled={!hydratedReady||!revokeReason.trim()} onclick={()=>sync('revoke-source',{attributionId:attribution.id,reason:revokeReason}).then(saved=>{if(saved){if(sourceId===attribution.id)sourceId='';revokeReason='';}})}>Revoke attribution</button>{/if}{/if}<label class="ml-3"><input type="radio" name="seal-source" value={attribution.id} bind:group={sourceId} disabled={!hydratedReady||!!attribution.revokedAt}/>Use for seal</label></article>{/each}
</section>
